<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/../includes/portal.php';requireRole(['Admin']);
$q=$pdo->query('SELECT d.id,d.original_name,d.status,d.note,d.submitted_at,r.name AS requirement,u.full_name,s.student_number FROM scholar_documents d JOIN scholars s ON s.id=d.scholar_id JOIN users u ON u.id=s.user_id JOIN document_requirements r ON r.id=d.requirement_id ORDER BY d.submitted_at DESC');$items=$q->fetchAll();portalStart('Document Review','documents.php');
foreach($items as $d){echo '<div class="portal-panel"><h2>'.h($d['requirement']).' — '.h($d['full_name']).'</h2><p>'.h($d['original_name']).' · '.h($d['student_number']).' · '.h($d['status']).'</p><small>Submitted '.h($d['submitted_at']).'</small><p><a href="../document_download.php?id='.h($d['id']).'">Download submitted file</a></p><form class="portal-form" method="post" action="../portal_action.php">'.csrf_field().'<input type="hidden" name="action" value="review_document"><input type="hidden" name="back" value="documents.php"><input type="hidden" name="id" value="'.h($d['id']).'"><label>Reviewer note<input name="note" maxlength="500" value="'.h($d['note']).'"></label><label>Decision<select name="status"><option>Approved</option><option>Rejected</option></select></label><button class="portal-button">Save review</button></form></div>';}if(!$items)portalNotice('No documents submitted yet.');portalEnd();